import type { TypegenCollection, TypegenField, TypegenRelation } from '../typegen-service';

/** A JSON Schema 2020-12 object as embedded in an OpenAPI 3.1 document. */
export type JsonSchema = Record<string, unknown>;

/**
 * Field type → JSON Schema. Mirrors `mapScalarFieldType` in
 * `packages/sdk/src/typegen/index.ts` entry for entry, so a client generated
 * from the OpenAPI document (`openapi-typescript`) and one generated by
 * `lumibase typegen` agree on every scalar: `string`→string,
 * `integer|bigInteger|decimal`→number, `boolean`→boolean, `json`→unknown.
 * `field-schema.test.ts` holds the two tables to each other.
 */
export const FIELD_TYPE_JSON_SCHEMA: Readonly<Record<string, JsonSchema>> = Object.freeze({
  string: { type: 'string' },
  text: { type: 'string' },
  hash: { type: 'string' },
  csv: { type: 'string' },
  integer: { type: 'integer' },
  bigInteger: { type: 'integer', format: 'int64' },
  decimal: { type: 'number' },
  boolean: { type: 'boolean' },
  json: {},
  uuid: { type: 'string', format: 'uuid' },
  date: { type: 'string', format: 'date' },
  datetime: { type: 'string', format: 'date-time' },
  time: { type: 'string', format: 'time' },
  timestamp: { type: 'string', format: 'date-time' },
  geometry: { type: 'object', additionalProperties: true, description: 'GeoJSON geometry object.' },
});

/** Interface ids with a wire shape different from their storage type. */
export const TRANSLATABLE_INTERFACE = 'translatable-text';
export const FILE_INTERFACE = 'file';
export const FILES_INTERFACE = 'files';

export type FieldShape = 'item' | 'projection' | 'input';

export interface FieldSchemaContext {
  collection: TypegenCollection;
  /** Encrypted values are returned decrypted (else masked as `'***'`). */
  readDecrypted: boolean;
  /** `$ref` to a related collection's projection, or null when undocumented. */
  projectionRef: (collection: string) => string | null;
  /** Primary-key schema of a collection (string or integer). */
  primaryKeySchema: (collection: string) => JsonSchema;
}

/** Allow `null` alongside an existing schema. */
export function withNull(schema: JsonSchema): JsonSchema {
  if (Object.keys(schema).length === 0) return schema; // `{}` already accepts null
  const type = schema['type'];
  if (typeof type === 'string' && !('enum' in schema)) return { ...schema, type: [type, 'null'] };
  if (typeof type === 'string' && Array.isArray(schema['enum'])) {
    return { ...schema, type: [type, 'null'], enum: [...(schema['enum'] as unknown[]), null] };
  }
  return { anyOf: [schema, { type: 'null' }] };
}

/** Same nullability rule as the SDK's `nullable()` helper. */
export function isNullable(field: TypegenField): boolean {
  return !field.required || field.nullable;
}

const expandedObject: JsonSchema = {
  type: 'object',
  description: 'Expanded record (requested with `fields=<name>.*`).',
};

function relationFor(field: TypegenField, collection: TypegenCollection): TypegenRelation | undefined {
  return collection.relations.find((relation) => relation.field === field.name);
}

function referenceOrId(target: string, ctx: FieldSchemaContext, shape: FieldShape): JsonSchema {
  const id = ctx.primaryKeySchema(target);
  if (shape !== 'projection') return id;
  const ref = ctx.projectionRef(target);
  return ref ? { anyOf: [id, { $ref: ref }] } : { anyOf: [id, expandedObject] };
}

function enumSchema(values: readonly unknown[]): JsonSchema | null {
  const strings = values.filter((value): value is string => typeof value === 'string');
  return strings.length > 0 ? { type: 'string', enum: [...new Set(strings)] } : null;
}

/**
 * JSON Schema for one user field, or null when the field has no wire value
 * (a presentation alias with no relation behind it).
 */
export function fieldSchema(field: TypegenField, ctx: FieldSchemaContext, shape: FieldShape): JsonSchema | null {
  const relation = relationFor(field, ctx.collection);
  let schema: JsonSchema;

  if (field.kind === 'm2o' && field.target) {
    schema = referenceOrId(field.target, ctx, shape);
  } else if (relation && (relation.kind === 'o2m' || relation.kind === 'm2m')) {
    schema = { type: 'array', items: referenceOrId(relation.target, ctx, shape) };
  } else if (relation?.kind === 'm2a' || field.kind === 'm2a') {
    schema = {
      type: 'array',
      items: {
        type: 'object',
        properties: { collection: { type: 'string' }, item: {} },
        required: ['collection', 'item'],
      },
    };
  } else if (field.interface === TRANSLATABLE_INTERFACE) {
    schema = {
      type: 'object',
      description: 'Per-locale values keyed by locale code (e.g. `{ "en": "…", "vi": "…" }`).',
      additionalProperties: { type: 'string' },
    };
  } else if (field.interface === FILE_INTERFACE) {
    const id: JsonSchema = { type: 'string', description: 'File id (`/api/v1/files/{id}`).' };
    schema = shape === 'projection' ? { anyOf: [id, expandedObject] } : id;
  } else if (field.interface === FILES_INTERFACE) {
    const id: JsonSchema = { type: 'string', description: 'File id (`/api/v1/files/{id}`).' };
    schema = { type: 'array', items: shape === 'projection' ? { anyOf: [id, expandedObject] } : id };
  } else if (field.type === 'alias') {
    return null;
  } else {
    const fromEnum = field.enum && field.enum.length > 0 ? enumSchema(field.enum) : null;
    schema = fromEnum ?? { ...(FIELD_TYPE_JSON_SCHEMA[field.type] ?? {}) };
  }

  if (field.encrypted && !ctx.readDecrypted && shape !== 'input') {
    schema = { anyOf: [schema, { const: '***', description: 'Masked: caller lacks `read_decrypted`.' }] };
  }
  if (isNullable(field)) schema = withNull(schema);
  if (field.readonly && shape !== 'input') schema = { ...schema, readOnly: true };
  return schema;
}
